head.script:
scwin.onpageload = function() {
	scwin.popupId = $p.getParameter("popupID");
	scwin.ibx_openPopup_onclick();
};

scwin.ibx_openPopup_onclick = function(e) {
	var options = {
		id: "popup2",
		type: "wframePopup",
		width: "600px",
		height: "400px",
		top: "130px",
		left: "400px",
		popupName: "openPopup2",
		modal: true,
		scrollbars: "true",
		resizable: "true",
		menubar: true,
		useModalStack: true,
		alwaysOnTop: false
	};
	$p.openPopup("/sample/common_link/p_popup_openPopup_WPFF-208_(WSQ-3494)_wframe2.xml", options);
};
